import os
import re
import tempfile
import zipfile
import xml.etree.ElementTree as ET

xlsx = 'data/openipf.xlsx'
main_ns = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
r_ns = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
ET.register_namespace('', main_ns)
ET.register_namespace('r', r_ns)
NS = {'m': main_ns}
needed = ['Name', 'Sex', 'BodyweightKg', 'Best3SquatKg', 'Best3BenchKg', 'Best3DeadliftKg']
cell_re = re.compile(r'([A-Z]+)([0-9]+)')

def col_to_num(col):
    n = 0
    for ch in col:
        n = n * 26 + ord(ch) - 64
    return n

def num_to_col(n):
    out = ''
    while n:
        n, rem = divmod(n - 1, 26)
        out = chr(65 + rem) + out
    return out

def cell_col(ref):
    return col_to_num(cell_re.match(ref).group(1))

def fmt_num(value):
    if value in (None, ''):
        return ''
    num = round(float(value), 3)
    if num.is_integer():
        return str(int(num))
    return f'{num:.3f}'.rstrip('0').rstrip('.')

def get_shared_strings(z):
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    strings = []
    for si in root.findall(f'{{{main_ns}}}si'):
        strings.append(''.join(t.text or '' for t in si.iter(f'{{{main_ns}}}t')))
    return strings

def get_cell_value(c, shared):
    t = c.attrib.get('t')
    v = c.find('m:v', NS)
    if t == 's':
        return shared[int(v.text)] if v is not None and v.text not in (None, '') else ''
    if t == 'inlineStr':
        return ''.join(node.text or '' for node in c.iter(f'{{{main_ns}}}t'))
    return v.text if v is not None else ''

def text_cell(ref, text):
    c = ET.Element(f'{{{main_ns}}}c', {'r': ref, 't': 'inlineStr'})
    is_el = ET.SubElement(c, f'{{{main_ns}}}is')
    t_el = ET.SubElement(is_el, f'{{{main_ns}}}t')
    if text and (text[:1].isspace() or text[-1:].isspace()):
        t_el.set('{http://www.w3.org/XML/1998/namespace}space', 'preserve')
    t_el.text = text or ''
    return c

def number_cell(ref, value):
    c = ET.Element(f'{{{main_ns}}}c', {'r': ref})
    v = ET.SubElement(c, f'{{{main_ns}}}v')
    try:
        v.text = fmt_num(value)
    except (TypeError, ValueError):
        c.set('t', 'inlineStr')
        c.remove(v)
        is_el = ET.SubElement(c, f'{{{main_ns}}}is')
        t_el = ET.SubElement(is_el, f'{{{main_ns}}}t')
        t_el.text = '' if value is None else str(value)
    return c

def formula_cell(ref, formula, cached):
    c = ET.Element(f'{{{main_ns}}}c', {'r': ref})
    f = ET.SubElement(c, f'{{{main_ns}}}f')
    f.text = formula
    v = ET.SubElement(c, f'{{{main_ns}}}v')
    v.text = fmt_num(cached) if cached not in (None, '') else ''
    return c

def total_formula(row):
    return f'ROUND(SUM(D{row}:F{row}),3)'

def dots_formula(row):
    bw_m = f'ROUND(MAX(40,MIN(C{row},210)),3)'
    bw_f = f'ROUND(MAX(40,MIN(C{row},150)),3)'
    male_den = f'(-0.000001093*{bw_m}"'^4+0.0007391293*{bw_m}''^3-0.1918759221*{bw_m}''^2+24.0900756*{bw_m}-307.75076)'"'
    female_den = f'(-0.0000010706*{bw_f}"'^4+0.0005158568*{bw_f}''^3-0.1126655495*{bw_f}''^2+13.6175032*{bw_f}-57.96288)'"'
    return f'IF(OR(B{row}=\"\",C{row}=\"\",G{row}=\"\",AND(B{row}<>\"M\",B{row}<>\"F\")),\"\",ROUND(G{row}*IF(B{row}=\"M\",500/{male_den},500/{female_den}),3))'

def calc_total(values):
    total = 0.0
    for v in values:
        if v not in (None, ''):
            total += float(v)
    return round(total, 3)

def calc_dots(sex, bw, total):
    if sex not in ('M', 'F') or bw in (None, '') or total in (None, ''):
        return ''
    bw = round(float(bw), 3)
    if sex == 'M':
        w = round(max(40, min(bw, 210)), 3)
        den = -0.000001093*w**4 + 0.0007391293*w**3 - 0.1918759221*w**2 + 24.0900756*w - 307.75076
    else:
        w = round(max(40, min(bw, 150)), 3)
        den = -0.0000010706*w**4 + 0.0005158568*w**3 - 0.1126655495*w**2 + 13.6175032*w - 57.96288
    return round(round(total, 3) * 500 / den, 3)

with zipfile.ZipFile(xlsx, 'r') as zin:
    shared = get_shared_strings(zin)
    data_root = ET.fromstring(zin.read('xl/worksheets/sheet1.xml'))
    data_rows = data_root.find('m:sheetData', NS).findall('m:row', NS)
    headers_by_col = {cell_col(c.attrib['r']): get_cell_value(c, shared) for c in data_rows[0].findall('m:c', NS)}
    source_cols = []
    for name in needed:
        matches = [col for col, header in headers_by_col.items() if header == name]
        if not matches:
            raise SystemExit(f'Missing required column: {name}')
        source_cols.append(matches[0])

    out_root = ET.fromstring(zin.read('xl/worksheets/sheet2.xml'))
    old_sheet_data = out_root.find('m:sheetData', NS)
    insert_index = list(out_root).index(old_sheet_data)
    out_root.remove(old_sheet_data)
    sheet_data = ET.Element(f'{{{main_ns}}}sheetData')

    header_row = ET.SubElement(sheet_data, f'{{{main_ns}}}row', {'r': '1'})
    for idx, name in enumerate(needed + ['TotalKg', 'Dots'], start=1):
        header_row.append(text_cell(f'{num_to_col(idx)}1', name))

    for out_r, data_row in enumerate(data_rows[1:], start=2):
        source_by_col = {cell_col(c.attrib['r']): c for c in data_row.findall('m:c', NS)}
        copied = []
        row_el = ET.SubElement(sheet_data, f'{{{main_ns}}}row', {'r': str(out_r)})
        for out_c, src_col in enumerate(source_cols, start=1):
            value = get_cell_value(source_by_col[src_col], shared) if src_col in source_by_col else ''
            copied.append(value)
            ref = f'{num_to_col(out_c)}{out_r}'
            if needed[out_c - 1] in ('Name', 'Sex'):
                row_el.append(text_cell(ref, value))
            else:
                row_el.append(number_cell(ref, value))
        total = calc_total(copied[3:6])
        dots = calc_dots(copied[1], copied[2], total)
        row_el.append(formula_cell(f'G{out_r}', total_formula(out_r), total))
        row_el.append(formula_cell(f'H{out_r}', dots_formula(out_r), dots))

    out_root.insert(insert_index, sheet_data)
    dim = out_root.find('m:dimension', NS)
    if dim is None:
        dim = ET.Element(f'{{{main_ns}}}dimension')
        out_root.insert(0, dim)
    dim.set('ref', f'A1:H{len(data_rows)}')
    xml_bytes = ET.tostring(out_root, encoding='utf-8', xml_declaration=True)

    fd, tmp = tempfile.mkstemp(suffix='.xlsx', dir=os.path.dirname(xlsx) or '.')
    os.close(fd)
    try:
        with zipfile.ZipFile(tmp, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
            for item in zin.infolist():
                content = zin.read(item.filename)
                if item.filename == 'xl/worksheets/sheet2.xml':
                    content = xml_bytes
                zout.writestr(item, content)
        os.replace(tmp, xlsx)
    except Exception:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise
print('Rebuilt Dots sheet with formulas and cached 3-decimal results.')
PY"

